require_once __DIR__.'/../includes/auth.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST')json_response(['error'=>'Method not allowed'],405);verify_api_csrf();$in=json_decode(file_get_contents('php://input'),true)??[];$mid=filter_var($in['message_id']??null,FILTER_VALIDATE_INT);$action=(string)($in['action']??'');$text=trim((string)($in['message']??''));$uid=current_user_id();$st=$pdo->prepare('SELECT message_id,conversation_id,sender_id,message_type,attachment_path FROM messages WHERE message_id=?');$st->execute([$mid]);$m=$st->fetch();if(!$m||!is_member($pdo,(int)$m['conversation_id'],$uid))json_response(['error'=>'Message not found'],404);if((int)$m['sender_id']!==$uid)json_response(['error'=>'You can only edit or delete your own messages.'],403);if($action==='edit'){if($m['message_type']!=='text'||$text===''||mb_strlen($text)>4000)json_response(['error'=>'Only text messages can be edited (1–4000 characters).'],422);$pdo->prepare('UPDATE messages SET message_text=?,edited_at=NOW() WHERE message_id=?')->execute([$text,$mid]);json_response(['ok'=>true]);}if($action==='delete'){if($m['attachment_path']){$file=dirname(__DIR__).'/'.ltrim($m['attachment_path'],'/');if(is_file($file))@unlink($file);}$pdo->prepare("UPDATE messages SET message_text=NULL,attachment_path=NULL,attachment_name=NULL,message_type='text',deleted_at=NOW() WHERE message_id=?")->execute([$mid]);json_response(['ok'=>true]);}json_response(['error'=>'Unknown action'],422);
